WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id ORDER BY cost DESC NULLS LAST, id ASC) AS row_num FROM shipments) t WHERE row_num = 1) SELECT CASE WHEN cost >= 104 THEN 'PREMIUM' ELSE 'STANDARD' END AS cost_tier, PERCENTILE_APPROX(cost, 0.5) AS cost_p50, SIZE(COLLECT_SET(status)) AS num_status, COUNT_IF(carrier = 'FedEx') AS fedex_events FROM latest GROUP BY cost_tier HAVING SIZE(COLLECT_SET(status)) < 1
